    input  wire        s3_rd_start, input wire [63:0] s3_rd_addr, input wire [7:0] s3_rd_len,
    output wire [63:0] s3_rd_data,  output wire s3_rd_data_valid, output wire s3_rd_done, output wire s3_rd_error,
    input  wire        s3_wr_start, input wire [63:0] s3_wr_addr, input wire [7:0] s3_wr_len,
    input  wire [63:0] s3_wr_data,  input wire [7:0] s3_wr_strb,  output wire s3_wr_data_ready, output wire s3_wr_done, output wire s3_wr_error,

