        if (!rst_n) begin
            rd_grant_r <= 2'd0;
            rd_locked  <= 1'b0;
            rd_pend    <= 4'd0;
            m_rd_start <= 1'b0;
            m_rd_addr  <= 64'd0;
            m_rd_len   <= 8'd0;
