    assign s1_rd_data_valid = m_rd_data_valid && (rd_grant == 2'd1);
    assign s2_rd_data_valid = m_rd_data_valid && (rd_grant == 2'd2);
    assign s3_rd_data_valid = m_rd_data_valid && (rd_grant == 2'd3);

    assign s0_rd_done = m_rd_done && (rd_grant == 2'd0);
    assign s1_rd_done = m_rd_done && (rd_grant == 2'd1);
    assign s2_rd_done = m_rd_done && (rd_grant == 2'd2);
    assign s3_rd_done = m_rd_done && (rd_grant == 2'd3);

    assign s0_rd_error = m_rd_error && (rd_grant == 2'd0);
    assign s1_rd_error = m_rd_error && (rd_grant == 2'd1);
    assign s2_rd_error = m_rd_error && (rd_grant == 2'd2);
    assign s3_rd_error = m_rd_error && (rd_grant == 2'd3);

    // =========================================================================
    // Write channel grant (independent of the read channel)
    // =========================================================================
    reg [1:0] wr_grant_r;
    reg       wr_locked;

