    reg [63:0] wr_addr_q [0:3];
    reg [7:0]  wr_len_q  [0:3];

    wire [1:0] wr_pick = wr_pend[0] ? 2'd0 :
                         wr_pend[1] ? 2'd1 :
                         wr_pend[2] ? 2'd2 : 2'd3;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_grant_r <= 2'd0;
            wr_locked  <= 1'b0;
            wr_pend    <= 4'd0;
            m_wr_start <= 1'b0;
            m_wr_addr  <= 64'd0;
            m_wr_len   <= 8'd0;
        end else begin
            m_wr_start <= 1'b0;

            if (!wr_locked) begin
                if (|wr_pend) begin
                    wr_grant_r       <= wr_pick;
                    wr_locked        <= 1'b1;
                    wr_pend[wr_pick] <= 1'b0;
                    m_wr_start       <= 1'b1;
                    m_wr_addr        <= wr_addr_q[wr_pick];
                    m_wr_len         <= wr_len_q[wr_pick];
